import "core-js/modules/es6.regexp.split";
import "core-js/modules/es6.function.name";
import { citypeList } from "@/api/system/ciModel";
import { importCi } from "@/api/cmdb/ciModel";
import website from '@/config/website';
import { Base64 } from 'js-base64';
import crypto from "@/util/crypto";
import { serialize } from '@/util/util';
import { getToken } from '@/util/auth';
import iconList from "./iconList";
import uploadModel from "./uploadModel";
var formData = new FormData();
export default {
  components: {
    iconList: iconList,
    uploadModel: uploadModel
  },
  props: ["isShow"],
  data: function data() {
    return {
      submitForm: {
        icon: 'tsfont-ci',
        isMenu: 0,
        isAbstract: 0
      },
      rules: {
        typeId: [{
          required: true,
          message: '模型层级不能为空',
          trigger: 'blur'
        }],
        name: [{
          required: true,
          message: '唯一标识不能为空',
          trigger: 'blur'
        }],
        label: [{
          required: true,
          message: '名称不能为空',
          trigger: 'blur'
        }]
      },
      ciTypeList: [],
      url: '/api/idevelop-cmdb/cmdb/ci/import',
      headers: {
        Authorization: undefined,
        'Idevelop-Auth': undefined
      },
      fileList: [],
      // 弹窗
      showIcon: false
    };
  },
  mounted: function mounted() {
    this.getDicts();
  },
  methods: {
    // 字典值
    getDicts: function getDicts() {
      var _this = this;
      // 模型层级
      citypeList().then(function (res) {
        _this.ciTypeList = res.Return;
      });
    },
    // 获得层级名称
    changeCitype: function changeCitype(val) {
      for (var i = 0; i < this.ciTypeList.length; i++) {
        var item = this.ciTypeList[i];
        if (item.id === val) this.submitForm.typeName = item.name;
      }
    },
    changeFile: function changeFile(file) {
      if (file.name.split('.')[1] !== 'model') {
        this.$message({
          type: 'warning',
          message: '请上传.model类型文件！'
        });
        this.fileList = [];
        return false;
      }
    },
    beforeUpload: function beforeUpload(file) {
      formData.append('file', file);
      this.headers['Authorization'] = "Basic ".concat(Base64.encode("".concat(website.clientId, ":").concat(website.clientSecret)));
      this.headers['Idevelop-Auth'] = 'bearer ' + getToken();
    },
    uploadFile: function uploadFile() {
      var _this2 = this;
      this.$refs.submitForm.validate(function (valid) {
        if (valid) {
          formData.append('icon', _this2.submitForm.icon);
          formData.append('name', _this2.submitForm.name);
          formData.append('label', _this2.submitForm.label);
          formData.append('typeId', _this2.submitForm.typeId);
          importCi(formData).then(function (res) {
            _this2.$message({
              type: 'success',
              message: '保存成功！'
            });
            _this2.$emit('saveCi');
            _this2.saveLoading = false;
          }).catch(function () {
            _this2.saveLoading = false;
          });
        }
      });
    },
    save: function save() {
      this.$refs.uoload.submit();
      // this.$refs.submitForm.validate((valid) => {
      //   if(valid) {
      //     this.saveLoading = true
      //     console
      //     importCi(this.submitForm).then(res => {
      //       this.$message({
      //         type: 'success',
      //         message: '保存成功！'
      //       });
      //       this.$emit('saveCi')
      //       this.saveLoading = false
      //     }).catch(() => {
      //       this.saveLoading = false
      //     })
      //   }
      // })
    },
    selectIcon: function selectIcon() {
      this.showIcon = true;
    },
    setIcon: function setIcon(val) {
      this.showIcon = false;
      this.submitForm.icon = val;
    }
  }
};
